import{_ as t,o as i,c as r,an as a}from"./chunks/framework.Cn5sLgV6.js";const u=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/index.md","filePath":"getting-started/index.md","lastUpdated":null}'),s={name:"getting-started/index.md"};function n(o,e,d,l,g,h){return i(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started {#getting-started}&quot;">​</a></h1><p>A recurrence computes each value from its own past values, such as infections from earlier infections. A convolution weights the past values of another series, such as reported cases from earlier infections. <a href="/previews/PR859/lib/public#ComposableRecurrences.Recurrence"><code>Recurrence</code></a> and <a href="/previews/PR859/lib/public#ComposableRecurrences.Convolution"><code>Convolution</code></a> are the two operators. Couplings link strata, such as towns, and modifiers add behaviour such as finite pools to each step. Every operator is differentiable. Operators run on CPU threads and on <a href="/previews/PR859/explanation/adjoints-and-backends#gpu-arrays">GPU arrays</a> through <a href="/previews/PR859/explanation/adjoints-and-backends#executors">executors</a>. On Julia 1.12 and later, a forward run compiles into a <a href="/previews/PR859/developer/extending-performance#trimming">trimmed executable</a> with <code>juliac</code>.</p><h2 id="Where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#Where-to-start" aria-label="Permalink to &quot;Where to start {#Where-to-start}&quot;">​</a></h2><ul><li><p>New to the package? <a href="/previews/PR859/getting-started/three-towns#tutorial-three-towns">Three towns, step by step</a> builds an outbreak model one part at a time.</p></li><li><p>Looking for an operator, coupling or modifier? See the <a href="/previews/PR859/explanation/api-overview#api-overview">API overview</a>.</p></li><li><p>Is your data weekly or monthly? See <a href="/previews/PR859/getting-started/time-units#time-units">Time units</a>.</p></li><li><p>Have a model in mind? Each tutorial in this section builds one, starting with <a href="/previews/PR859/getting-started/tutorials/renewal-then-delay#tutorial-renewal-delay">Renewal then delay</a>.</p></li><li><p>Coming from epidemiology? <a href="/previews/PR859/domain-guides/infectious-disease-models#infectious-disease-models">Infectious disease models</a> maps renewal processes, delays and occupancy to the package.</p></li><li><p>Want to know how it works? The How it works pages start with the <a href="/previews/PR859/explanation/api-overview#api-overview">API overview</a>.</p></li><li><p>Want to write your own modifier or coupling? See the <a href="/previews/PR859/developer/index#developer">Developer documentation</a>.</p></li><li><p>Want the full interface? See the <a href="/previews/PR859/lib/public#public-api">Public API</a>.</p></li><li><p>Need GPUs, an AD backend or distributions? See <a href="/previews/PR859/getting-started/index#extensions-overview">Extensions</a>.</p></li></ul><h2 id="extensions-overview" tabindex="-1">Extensions <a class="header-anchor" href="#extensions-overview" aria-label="Permalink to &quot;Extensions {#extensions-overview}&quot;">​</a></h2><p>Each extension loads by itself when you load its packages alongside ComposableRecurrences. None is needed to build or run a model.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Load</th><th style="text-align:right;">Adds</th><th style="text-align:right;">Use it for</th><th style="text-align:right;">Page</th></tr></thead><tbody><tr><td style="text-align:right;"><code>using Distributions</code></td><td style="text-align:right;">Discrete distributions as delay kernels</td><td style="text-align:right;">Delays from a named distribution</td><td style="text-align:right;"><a href="/previews/PR859/extensions/distributions#extension-distributions">Distributions</a></td></tr><tr><td style="text-align:right;"><code>using CensoredDistributions, Distributions</code></td><td style="text-align:right;">Continuous distributions as kernels, censored to whole lags</td><td style="text-align:right;">Continuous delays</td><td style="text-align:right;"><a href="/previews/PR859/extensions/censored-distributions#extension-censored-distributions">CensoredDistributions</a></td></tr><tr><td style="text-align:right;"><code>using ForwardDiff</code></td><td style="text-align:right;">Dual-number local step for couplings and modifiers without a <code>pullback!</code></td><td style="text-align:right;">Faster reverse-mode gradients through them</td><td style="text-align:right;"><a href="/previews/PR859/extensions/forward-diff#extension-forwarddiff">ForwardDiff</a></td></tr><tr><td style="text-align:right;"><code>using Enzyme</code></td><td style="text-align:right;">Enzyme reverse-mode rules</td><td style="text-align:right;">Enzyme gradients</td><td style="text-align:right;"><a href="/previews/PR859/extensions/enzyme#extension-enzyme">Enzyme</a></td></tr><tr><td style="text-align:right;"><code>using Mooncake</code></td><td style="text-align:right;">Mooncake reverse-mode rules and <code>test_adjoint</code></td><td style="text-align:right;">Mooncake gradients</td><td style="text-align:right;"><a href="/previews/PR859/extensions/mooncake#extension-mooncake">Mooncake</a></td></tr><tr><td style="text-align:right;"><code>using ADTypes, Enzyme, EnzymeTestUtils</code></td><td style="text-align:right;"><code>test_adjoint</code> for <code>AutoEnzyme</code></td><td style="text-align:right;">Testing a new rule</td><td style="text-align:right;"><a href="/previews/PR859/extensions/enzyme-test-utils#extension-enzyme-test-utils">EnzymeTestUtils</a></td></tr><tr><td style="text-align:right;"><code>using FFTW</code></td><td style="text-align:right;">FFT lag sums for <code>Convolution</code></td><td style="text-align:right;">Long kernels over long series</td><td style="text-align:right;"><a href="/previews/PR859/extensions/fftw#extension-fftw">FFTW</a></td></tr><tr><td style="text-align:right;"><code>using Functors</code></td><td style="text-align:right;"><code>convert_floats</code></td><td style="text-align:right;">Runs in <code>Float32</code></td><td style="text-align:right;"><a href="/previews/PR859/extensions/functors#extension-functors">Functors</a></td></tr><tr><td style="text-align:right;"><code>using KernelAbstractions</code></td><td style="text-align:right;"><code>Parallel</code> executor and Adapt rules</td><td style="text-align:right;">Kernels without a GPU package</td><td style="text-align:right;"><a href="/previews/PR859/extensions/kernel-abstractions#extension-kernel-abstractions">KernelAbstractions</a></td></tr><tr><td style="text-align:right;"><code>using CUDA, KernelAbstractions</code>, or any GPUArrays backend</td><td style="text-align:right;">Calls on device arrays, including CSR couplings, run as kernels</td><td style="text-align:right;">GPUs</td><td style="text-align:right;"><a href="/previews/PR859/extensions/gpuarrays#extension-gpuarrays">GPUArrays</a></td></tr><tr><td style="text-align:right;"><code>using Reactant, KernelAbstractions, CUDA</code></td><td style="text-align:right;">Compiled calls on traced arrays</td><td style="text-align:right;">Compiling a model with Reactant</td><td style="text-align:right;"><a href="/previews/PR859/extensions/reactant#extension-reactant">Reactant</a></td></tr></tbody></table><h2 id="Getting-help" tabindex="-1">Getting help <a class="header-anchor" href="#Getting-help" aria-label="Permalink to &quot;Getting help {#Getting-help}&quot;">​</a></h2><p>For usage questions, ask on the <a href="https://discourse.julialang.org" target="_blank" rel="noreferrer">Julia Discourse</a> or the <a href="https://community.epinowcast.org" target="_blank" rel="noreferrer">epinowcast community forum</a>, our home for epidemiological modelling questions. Please use <a href="https://github.com/EpiAware/ComposableRecurrences.jl/issues" target="_blank" rel="noreferrer">GitHub issues</a> for bug reports and feature requests only.</p>',9)])])}const p=t(s,[["render",n]]);export{u as __pageData,p as default};
